def classify_dxbw(elev, reg, slope):
    if elev is None or reg is None:
        return None
    tpi = elev - reg
    if tpi <= -15:
        return u'山间盆地'
    if tpi <= -5:
        if slope is not None and slope < 5:
            return u'宽谷盆地'
        return u'山地坡下'
    if tpi < 5:
        if slope is not None and slope < 5:
            return u'平原低阶'
        if slope is not None and slope < 15:
            return u'丘陵下部'
        return u'山地坡下'
    if tpi < 15:
        if elev > 500:
            return u'山地坡中'
        return u'丘陵中部'
    if elev > 500:
        return u'山地坡上'
    return u'丘陵上部'

